(function(){'use strict';const R=CritterRenderer.prototype,oldEvent=R.event,oldWorm=R.worm,oldDecor=R.decorations,oldEffects=R.effects;
R.event=function(e){oldEvent.call(this,e);if(e.type==='teleport'){this.focus(this.game.units[e.id]);this.rings.push({x:e.x,y:e.y,r:65,life:.6,max:.6});}if(e.type==='explosion'&&e.weapon===9){for(let i=0;i<16;i++)this.fx.push({x:e.x,y:e.y,vx:Math.cos(i/8*Math.PI)*160,vy:Math.sin(i/8*Math.PI)*160-80,life:1.5,max:1.5,size:4,color:'#fff3a3',type:'debris'});}};
R.worm=function(k,u,...args){oldWorm.call(this,k,u,...args);if(u.shield>0&&u.hp>0){k.save();k.strokeStyle='#a5f3e8';k.fillStyle='#a5f3e825';k.lineWidth=2;k.beginPath();k.ellipse(u.x,u.y-10,31,42,0,0,7);k.fill();k.stroke();k.restore();}};
R.decorations=function(k,back){const id=this.game.options.layout;if(id===undefined||id===0)return oldDecor.call(this,k,back);if(back)return;const t=Critters.THEMES[this.game.options.theme];for(const x of [140,335,710,910,1260,1460]){const y=this.game.heights[x];if(y>=this.game.water||!this.game.solid(x,y+2))continue;k.save();k.translate(x,y);k.strokeStyle='#3e5360';k.lineWidth=3;if([1,9].includes(id)){k.strokeStyle='#76975c';k.lineWidth=13;k.lineCap='round';k.beginPath();k.moveTo(0,0);k.lineTo(0,-65);k.moveTo(0,-25);k.lineTo(-19,-25);k.lineTo(-19,-45);k.moveTo(0,-38);k.lineTo(18,-38);k.lineTo(18,-57);k.stroke();}else if(id===3){k.fillStyle='#e3cda4';k.fillRect(-5,-48,10,48);k.fillStyle=x%3?'#e89b9a':'#b8a6dd';k.beginPath();k.ellipse(0,-48,36,21,0,Math.PI,Math.PI*2);k.fill();k.fillStyle='#f9e8c9';for(let i=0;i<3;i++){k.beginPath();k.arc(-17+i*16,-53-i%2*5,4,0,7);k.fill();}}else if([5,11].includes(id)){k.fillStyle='#68728a';k.fillRect(-22,-65,44,65);for(let i=0;i<3;i++)k.fillRect(-22+i*17,-76,10,15);k.fillStyle='#d9b574';k.fillRect(-5,-49,10,18);}else if([6,8].includes(id)){k.fillStyle=id===6?'#d1f4f7':'#b9a2ec';k.beginPath();k.moveTo(-26,0);k.lineTo(-13,-66);k.lineTo(1,-22);k.lineTo(16,-87);k.lineTo(31,0);k.fill();k.stroke();}else{k.fillStyle=t.earth;k.beginPath();k.moveTo(-28,0);k.lineTo(-21,-29);k.lineTo(4,-44);k.lineTo(30,-20);k.lineTo(35,0);k.fill();k.stroke();}k.restore();}};
R.effects=function(k,dt){oldEffects.call(this,k,dt);const id=this.game.options.layout;if(![6,7,10,11].includes(id))return;const t=this.reduced?0:this.time;k.save();for(let i=0;i<35;i++){let x=(i*89+t*(id===10?100:16))%1600,y=(i*47+t*(id===6?30:-22))%790;k.fillStyle=id===7?'#ffb16699':id===11?'#e4bcff99':'#e1f6ff99';k.beginPath();k.arc(x,y,id===6?2:1.6,0,7);k.fill();}k.restore();};
})();
